SELECT     "topics".*   FROM     "topics"     LEFT JOIN topic_users tu ON topics.id = tu.topic_id     AND tu.user_id = 13455   WHERE     ("topics"."deleted_at" IS NOT NULL)     AND (      topics.archetype = 'private_message'    )     AND (      topics.id IN (        SELECT           topic_id         FROM           topic_allowed_users         WHERE           user_id = 13455      )    )     AND (      topics.id IN (        SELECT           ta.topic_id         FROM           topic_allowed_users ta         WHERE           ta.user_id IN (2, 1995, 8307, 17621, 22980,-10)      )       OR topics.id IN (        SELECT           tg.topic_id         FROM           topic_allowed_groups tg         WHERE           tg.group_id IN (-10)      )    )     AND (      topics.id NOT IN (68559, 60069, 42145)    )     AND "topics"."visible" = 't'   ORDER BY     topics.bumped_at DESC   LIMIT     5
SELECT     "topics".*   FROM     "topics"     LEFT JOIN topic_users tu ON topics.id = tu.topic_id     AND tu.user_id = 13455     LEFT JOIN topic_allowed_users ta ON topics.id = ta.topic_id     AND ta.user_id = 13455     LEFT JOIN topic_allowed_users ta2 ON topics.id = ta2.topic_id     AND ta2.user_id IN (2, 1995, 8307, 17621, 22980,-10)     LEFT JOIN topic_allowed_groups tg ON topics.id = tg.topic_id     AND tg.group_id IN (-10)   WHERE     ("topics"."deleted_at" IS NOT NULL)     AND (      topics.archetype = 'private_message'    )     AND (ta.topic_id IS NOT NULL)     AND (      ta2.topic_id IS NOT NULL       OR tg.topic_id IS NOT NULL    )     AND (      topics.id NOT IN (68559, 60069, 42145)    )     AND "topics"."visible" = 't'   ORDER BY     topics.bumped_at DESC   LIMIT     5
SELECT     "topics".*   FROM     "topics"     LEFT JOIN topic_users tu ON topics.id = tu.topic_id     AND tu.user_id = 13455   WHERE     ("topics"."deleted_at" IS NOT NULL)     AND (      topics.archetype = 'private_message'    )     AND (      topics.id IN (        SELECT           topic_id         FROM           topic_allowed_groups tg           JOIN group_users gu ON gu.user_id = 13455           AND gu.group_id = tg.group_id         WHERE           gu.group_id IN (47)      )    )     AND (      topics.id IN (        SELECT           ta.topic_id         FROM           topic_allowed_users ta         WHERE           ta.user_id IN (32852,-10)      )       OR topics.id IN (        SELECT           tg.topic_id         FROM           topic_allowed_groups tg         WHERE           tg.group_id IN (-10)      )    )     AND (      topics.id NOT IN (        69933, 69995, 69988, 69984, 69968, 69973,         69971, 69952      )    )     AND "topics"."visible" = 't'   ORDER BY     topics.bumped_at DESC   LIMIT     3
SELECT     "topics".*   FROM     "topics"     LEFT JOIN topic_users tu ON topics.id = tu.topic_id     AND tu.user_id = 13455     LEFT JOIN (      SELECT         *       FROM         topic_allowed_groups _tg         LEFT JOIN group_users gu ON gu.user_id = 13455         AND gu.group_id = _tg.group_id         AND gu.group_id IN (47)    ) tg ON topics.id = tg.topic_id     LEFT JOIN topic_allowed_users ta2 ON topics.id = ta2.topic_id     AND ta2.user_id IN (32852)   WHERE     ("topics"."deleted_at" IS NOT NULL)     AND (      topics.archetype = 'private_message'    )     AND (tg.topic_id IS NOT NULL)     AND (ta2.topic_id IS NOT NULL)     AND (      topics.id NOT IN (        69933, 69995, 69988, 69984, 69968, 69973,         69971, 69952      )    )     AND "topics"."visible" = 't'   ORDER BY     topics.bumped_at DESC   LIMIT     3
SELECT     DISTINCT "child_themes"."child_theme_id"   FROM     "child_themes"   WHERE     "child_themes"."parent_theme_id" = 1050

SELECT     COUNT(*)   FROM     "topics"   WHERE     ("topics"."deleted_at" IS NOT NULL)     AND (      id in (        SELECT           topic_id         FROM           posts p           JOIN topics t2 ON t2.id = p.topic_id         WHERE           p.deleted_at IS NOT NULL           AND t2.user_id <> p.user_id           AND p.user_id = 13      )    )

SELECT     posts.*  FROM     "posts"     INNER JOIN "topics" ON "topics"."id" = "posts"."topic_id"     AND ("topics"."deleted_at" IS NOT NULL)   WHERE     ("posts"."deleted_at" IS NOT NULL)     AND (      posts.created_at > '2020-04-09 05:33:01.710426'    )     AND "posts"."topic_id" IN (      SELECT         "topics"."id"       FROM         "topics"         LEFT OUTER JOIN topic_users ON topic_users.topic_id = topics.id         AND topic_users.user_id = 133         LEFT OUTER JOIN category_users ON category_users.category_id = topics.category_id         AND category_users.user_id = 133         LEFT OUTER JOIN users ON users.id = topics.user_id       WHERE         ("topics"."deleted_at" IS NOT NULL)         AND "topics"."visible" = TRUE         AND (          topics.category_id IS NULL           OR topics.category_id IN (            SELECT               id             FROM               categories             WHERE               NOT read_restricted          )        )         AND "topics"."closed" = FALSE         AND "topics"."archived" = FALSE         AND (          COALESCE(            topic_users.notification_level,             1          ) <> 0        )         AND (          topics.created_at > '1970-01-01 00:00:00'        )         AND (          topics.created_at < '2020-05-09 05:28:01.737977'        )         AND (          topics.archetype <> 'private_message'        )         AND (          COALESCE(users.trust_level, 0) > 0        )    )     AND (posts.post_type = 1)     AND (      posts.deleted_at IS NOT NULL       AND posts.hidden = false       AND posts.user_deleted = false    )     AND (      posts.post_number > 1       AND posts.score > 75.0    )     AND (      posts.created_at < '2020-05-09 05:28:01.741093'    )   ORDER BY     posts.score DESC,     posts.created_at ASC   LIMIT     5

SELECT     "posts".*   FROM     "posts"     INNER JOIN "topics" ON "topics"."id" = "posts"."topic_id"     AND ("topics"."deleted_at" IS NOT NULL)   WHERE     ("posts"."deleted_at" IS NOT NULL)     AND (      posts.id NOT IN (        SELECT           post_id         from           post_search_data         WHERE           locale = 'en_US'      )    )   LIMIT     10000
SELECT     "posts".*   FROM     "posts"     INNER JOIN "topics" ON "topics"."id" = "posts"."topic_id"     AND ("topics"."deleted_at" IS NOT NULL)   WHERE     ("posts"."deleted_at" IS NOT NULL)     AND (      posts.id IN (        SELECT           p2.id         FROM           posts p2           LEFT JOIN post_search_data pd ON locale = 'en_US'           AND p2.id = pd.post_id         WHERE           pd.post_id IS NULL      )    )   LIMIT     10000
SELECT users.id FROM "users" LEFT JOIN category_users cu ON users.id = cu.user_id INNER JOIN categories c ON c.id = cu.category_id WHERE ( c.id = '3613' AND cu.notification_level IS NULL)
SELECT    COUNT(*)  FROM    "badges"    INNER JOIN "user_badges" ON "badges"."id" = "user_badges"."badge_id"  WHERE    "user_badges"."user_id" = 2112    AND badges.enabled    AND "badges"."id" = 1
SELECT    "groups".*  FROM    "groups"    LEFT JOIN group_users gu ON gu.group_id = groups.id    AND gu.user_id = 296    AND gu.owner  WHERE    groups.visibility_level IN (0, 1, 2, 4)    OR (     groups.visibility_level = 3      AND gu.id IS NOT NULL   )    AND (groups.id > 0)    AND (     name ILIKE '%GO%'      OR full_name ILIKE '%GO%'   )  ORDER BY    name ASC
SELECT    directory_items.likes_received AS alias_0,    "directory_items"."id"  FROM    "directory_items"    LEFT OUTER JOIN "users" ON "users"."id" = "directory_items"."user_id"    LEFT OUTER JOIN "group_users" ON "group_users"."user_id" = "users"."id"  WHERE    "directory_items"."period_type" = 1    AND "group_users"."group_id"  = 2898  ORDER BY    directory_items.likes_received DESC  LIMIT    50 OFFSET 0
SELECT distinct "posts".* FROM "posts" INNER JOIN "post_search_data" ON "post_search_data"."post_id" = "posts"."id" INNER JOIN "topics" ON "topics"."id" = "posts"."topic_id" AND ("topics"."deleted_at" IS NULL) LEFT JOIN categories ON categories.id = topics.category_id WHERE ("posts"."deleted_at" IS NULL) AND "posts"."post_type" IN (1, 2, 3) AND (topics.visible) AND ( topics.archetype <> 'private_message' ) AND ( topics.id IN ( SELECT distinct tt.topic_id FROM topic_tags tt WHERE tt.tag_id in ( SELECT distinct tag_id FROM tag_group_memberships WHERE tag_group_id = 504 ) ) ) AND ( categories.id NOT IN ( SELECT distinct categories.id WHERE categories.search_priority = 1 ) ) AND ( (categories.id IS NULL) OR (NOT categories.read_restricted) ) AND ( posts.topic_id NOT in (18674, 18673, 18672) ) ORDER BY posts.created_at DESC LIMIT 9 OFFSET 0"
SELECT    "groups"."id",    "groups"."name"  FROM    "groups"    INNER JOIN "group_users" ON "groups"."id" = "group_users"."group_id"  WHERE    "group_users"."user_id" = 296 AND   groups.visibility_level IN (0, 1, 2, 3, 4)  ORDER BY    name ASC
SELECT    COUNT(*)  FROM    "groups"    LEFT JOIN group_users gu ON gu.group_id = groups.id    AND gu.user_id = 783    AND gu.owner  WHERE    (groups.id > 0)    AND (     groups.visibility_level IN (0, 1, 2, 4)      OR (       groups.visibility_level = 3        AND gu.id IS NOT NULL     )   )    AND (     groups.members_visibility_level IN (0, 1, 2, 4)      OR (       groups.visibility_level = 3        AND gu.id IS NOT NULL     )   )    AND (gu.user_id = 780)    AND (     automatic IS FALSE      OR groups.id = 2   )
SELECT    "groups".*  FROM    "groups"    LEFT JOIN group_users gu ON gu.group_id = groups.id    AND gu.user_id = 296    AND gu.owner  WHERE    (groups.id > 0) AND   groups.visibility_level IN (0, 1, 2, 4)    OR (     groups.visibility_level = 3      AND gu.id IS NOT NULL   )    AND (     automatic IS FALSE      OR groups.id = 2   )  ORDER BY    user_count DESC  LIMIT    36 OFFSET 0
SELECT    "groups".*  FROM    "groups"    LEFT JOIN group_users gu ON gu.group_id = groups.id    AND gu.user_id = 296    AND gu.owner  WHERE    groups.id > 0    AND groups.visibility_level IN (0, 1, 2, 4)    OR (     groups.visibility_level = 3      AND gu.id IS NOT NULL   )    AND (     automatic IS FALSE      OR groups.id = 2   )  ORDER BY    name ASC  LIMIT    36 OFFSET 0
SELECT "groups"."id", "groups"."name" FROM "groups" LEFT JOIN group_users gu ON gu.group_id = groups.id AND gu.user_id = 296 AND gu.owner WHERE groups.visibility_level IN (0, 1, 2, 4) OR ( groups.visibility_level = 3 AND gu.id IS NOT NULL ) ORDER BY name ASC
SELECT    "posts".*  FROM    "posts"    INNER JOIN "topics" ON "topics"."id" = "posts"."topic_id"    LEFT JOIN post_search_data pd ON posts.id = pd.post_id WHERE    ("posts"."deleted_at" IS NULL)    AND ("topics"."deleted_at" IS NULL)    AND locale <> 'en_US' LIMIT    10000
